128	AddConstraint('bom', 'bom_ibfk_1', 'parent', 'stockmaster', 'stockid');
129	AddConstraint('bom', 'bom_ibfk_2', 'component', 'stockmaster', 'stockid');
130	AddConstraint('contractbom', 'contractbom_ibfk_3', 'stockid', 'stockmaster', 'stockid');
131	AddConstraint('custitem', 'custitem_ibfk_1', 'stockid', 'stockmaster', 'stockid');
132	AddConstraint('locstock', 'locstock_ibfk_2', 'stockid', 'stockmaster', 'stockid');
133	AddConstraint('loctransfers', 'loctransfers_ibfk_3', 'stockid', 'stockmaster', 'stockid');
134	AddConstraint('mrpdemands', 'mrpdemands_ibfk_2', 'stockid', 'stockmaster', 'stockid');
135	AddConstraint('offers', 'offers_ibfk_2', 'stockid', 'stockmaster', 'stockid');
136	AddConstraint('orderdeliverydifferenceslog', 'orderdeliverydifferenceslog_ibfk_1', 'stockid', 'stockmaster', 'stockid');
137	AddConstraint('pickreqdetails', 'pickreqdetails_ibfk_1', 'stockid', 'stockmaster', 'stockid');
138	AddConstraint('prices', 'prices_ibfk_1', 'stockid', 'stockmaster', 'stockid');
139	AddConstraint('purchdata', 'purchdata_ibfk_1', 'stockid', 'stockmaster', 'stockid');
140	AddConstraint('recurrsalesorderdetails', 'recurrsalesorderdetails_ibfk_2', 'stkcode', 'stockmaster', 'stockid');
141	AddConstraint('salescatprod', 'salescatprod_ibfk_1', 'stockid', 'stockmaster', 'stockid');
142	AddConstraint('salesorderdetails', 'salesorderdetails_ibfk_2', 'stkcode', 'stockmaster', 'stockid');
143	AddConstraint('stockcheckfreeze', 'stockcheckfreeze_ibfk_1', 'stockid', 'stockmaster', 'stockid');
144	AddConstraint('stockcounts', 'stockcounts_ibfk_1', 'stockid', 'stockmaster', 'stockid');
145	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_1', 'stockid', 'stockmaster', 'stockid');
146	// TODO determine if next 2 stockitemproperties constraints are redundant and if so delete
147	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_3', 'stockid', 'stockmaster', 'stockid');
148	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_5', 'stockid', 'stockmaster', 'stockid');
149	
150	// TODO review foreign key constraints in stockitemproperties table for redundant constraints (and delete)
151	
152	AddConstraint('stockmoves', 'stockmoves_ibfk_1', 'stockid', 'stockmaster', 'stockid');
153	AddConstraint('stockrequestitems', 'stockrequestitems_ibfk_2', 'stockid', 'stockmaster', 'stockid');
154	// TODO TODO determine if next stockrequestitems constraint is redundant and if so delete
155	AddConstraint('stockrequestitems', 'stockrequestitems_ibfk_4', 'stockid', 'stockmaster', 'stockid');
156	AddConstraint('stockserialitems', 'stockserialitems_ibfk_1', 'stockid', 'stockmaster', 'stockid');
157	AddConstraint('woitems', 'woitems_ibfk_1', 'stockid', 'stockmaster', 'stockid');
158	AddConstraint('worequirements', 'worequirements_ibfk_2', 'stockid', 'stockmaster', 'stockid');
159	
160	// 3.2 add grandchild fk constraints
161	AddConstraint('stockserialmoves', 'stockserialmoves_ibfk_2', array('stockid', 'serialno'), 'stockserialitems', array('stockid', 'serialno'));
162	AddConstraint('worequirements', 'worequirements_ibfk_3', array('wo', 'parentstockid'), 'woitems', array('wo', 'stockid'));
163	
164	
165	// 4. change size of IMPLICIT stockid child foreign key columns
166	// 4.1 columns named stockid (same as parent)
167	// 
168	// Use SQL query to obtain columns named "stockid" and manually remove columns
169	// listed in step 1.1
170	//
171	//   SELECT 
172	//       TABLE_NAME, 
173	//       COLUMN_NAME, 
174	//       DATA_TYPE
175	//   FROM 
176	//       information_schema.COLUMNS
177	//   WHERE 
178	//       COLUMN_NAME = 'stockid'
179	//       AND TABLE_SCHEMA = DATABASE()
180	//       AND TABLE_NAME != 'stockmaster';
181	//   
182	//   +------------------------------+-------------+-----------+
183	//   | TABLE_NAME                   | COLUMN_NAME | DATA_TYPE |
184	//   +------------------------------+-------------+-----------+
185	//   | assetmanager                 | stockid     | varchar   |
186	//   | ediitemmapping               | stockid     | varchar   |
187	//   | employees                    | stockid     | varchar   |
188	//   | lastcostrollup               | stockid     | char      |
189	//   | loctransfercancellations     | stockid     | varchar   |
190	//   | pickserialdetails            | stockid     | varchar   |
191	//   | pricematrix                  | stockid     | varchar   |
192	//   | relateditems                 | stockid     | varchar   |
193	//   | salesanalysis                | stockid     | varchar   |
194	//   | sellthroughsupport           | stockid     | varchar   |
195	//   | shipmentcharges              | stockid     | varchar   |
196	//   | stockdescriptiontranslations | stockid     | varchar   |
197	//   | stockserialmoves             | stockid     | varchar   |
198	//   | supplierdiscounts            | stockid     | varchar   |
199	//   | tenderitems                  | stockid     | varchar   |
200	//   | woserialnos                  | stockid     | varchar   |
201	//   +------------------------------+-------------+-----------+
202	//   16 columns
203	
204	// 4.1.1 drop foreign key constraint on stockserialmoves.stockid
205	// DropConstraint($Table, $Constraint)
206	DropConstraint('stockserialmoves', 'stockserialmoves_ibfk_2');  // fwiw this key was also dropped in 1.1.1 (and re-added in 1.3.2)
207	
208	// 4.1.2 changes sizes of implicit child fk columns
209	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
210	ChangeColumnSize('stockid', 'assetmanager',  'VARCHAR(64)', ' NOT NULL ', '', '64');
211	ChangeColumnSize('stockid', 'ediitemmapping',  'VARCHAR(64)', ' NOT NULL ', '', '64');
212	ChangeColumnSize('stockid', 'employees',  'VARCHAR(64)', ' NOT NULL ', '', '64');
213	ChangeColumnSize('stockid', 'lastcostrollup',  'VARCHAR(64)', ' NOT NULL ', '', '64');
214	ChangeColumnSize('stockid', 'loctransfercancellations',  'VARCHAR(64)', ' NOT NULL ', '', '64');
215	ChangeColumnSize('stockid', 'pickserialdetails',  'VARCHAR(64)', ' NOT NULL ', '', '64');
216	ChangeColumnSize('stockid', 'pricematrix',  'VARCHAR(64)', ' NOT NULL ', '', '64');
217	ChangeColumnSize('stockid', 'relateditems',  'VARCHAR(64)', ' NOT NULL ', '', '64');
218	ChangeColumnSize('stockid', 'salesanalysis',  'VARCHAR(64)', ' NOT NULL ', '', '64');
219	ChangeColumnSize('stockid', 'sellthroughsupport',  'VARCHAR(64)', ' NOT NULL ', '', '64');
220	ChangeColumnSize('stockid', 'shipmentcharges',  'VARCHAR(64)', ' NOT NULL ', '', '64');
221	ChangeColumnSize('stockid', 'stockdescriptiontranslations',  'VARCHAR(64)', ' NOT NULL ', '', '64');
222	ChangeColumnSize('stockid', 'stockserialmoves',  'VARCHAR(64)', ' NOT NULL ', '', '64');
223	ChangeColumnSize('stockid', 'supplierdiscounts',  'VARCHAR(64)', ' NOT NULL ', '', '64');
224	ChangeColumnSize('stockid', 'tenderitems',  'VARCHAR(64)', ' NOT NULL ', '', '64');
225	ChangeColumnSize('stockid', 'woserialnos',  'VARCHAR(64)', ' NOT NULL ', '', '64');
226	
227	// 4.1.3 add (re-add) foreign key constraint
228	// AddConstraint($Table, $Constraint, $Field, $ReferenceTable, $ReferenceField)
229	AddConstraint('stockserialmoves', 'stockserialmoves_ibfk_2', array('stockid', 'serialno'), 'stockserialitems', array('stockid', 'serialno'));
230	
231	
232	// 4.2 search for related columns named stkcode and change size (because "stkcode" was used as an explit fk constraint name)
233	//
234	// Use SQL query to obtain list of constraints named "stkcode" (because the name had been used
235	// as an explit fk contraint) and remove explicit constraints having the same name as those found in step 1.1
236	//
237	//   SELECT 
238	//       TABLE_NAME, 
239	//       COLUMN_NAME, 
240	//       DATA_TYPE
241	//   FROM 
242	//       information_schema.COLUMNS
243	//   WHERE 
244	//       COLUMN_NAME = 'stkcode'
245	//       AND TABLE_SCHEMA = DATABASE()
246	//       AND TABLE_NAME != 'stockmaster';
247	//   	
248	//   +-------------------------+-------------+-----------+
249	//   | TABLE_NAME              | COLUMN_NAME | DATA_TYPE |
250	//   +-------------------------+-------------+-----------+
251	//   | recurrsalesorderdetails | stkcode     | varchar   |
252	//   | salesorderdetails       | stkcode     | varchar   |
253	//   +-------------------------+-------------+-----------+
254	//   2 rows
255	
256	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
257	// - no need, already changed in 2.2
258	//ChangeColumnSize('stkcode', 'recurrsalesorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
259	// - no need, already changed in 2.2
260	//ChangeColumnSize('stkcode', 'salesorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
261	
262	
263	// 4.3 search for related columns defined as "varchar(20)" (original size of stockmaster.stockid) and change size
264	//   - per https://github.com/timschofield/webERP/wiki/PLM-Features-Increasing-stockid-size
265	//   - TODO review by someone with more understanding of the code than the author
266	//
267	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
268	ChangeColumnSize('related', 'relateditems', 'VARCHAR(64)', ' NOT NULL ', '', '64');
269	ChangeColumnSize('stockact', 'lastcostrollup', 'VARCHAR(64)', ' NOT NULL ', '', '64');
270	ChangeColumnSize('itemcode', 'purchorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
271	ChangeColumnSize('stockact', 'stockcategory', 'VARCHAR(64)', ' NOT NULL ', '', '64');
272	
273	// constraint on parentstockid has to be dropped first and re-added after changing size
274	DropConstraint('worequirements', 'worequirements_ibfk_3'); // compound fk constraint
275	ChangeColumnSize('parentstockid', 'worequirements', 'VARCHAR(64)', ' NOT NULL ', '', '64');
276	AddConstraint('worequirements', 'worequirements_ibfk_3', array('wo', 'parentstockid'), 'woitems', array('wo', 'stockid'));
277	
278	
279	// 4.4 search for related columns with "code" in their name and change size
280	//   - per https://github.com/timschofield/webERP/wiki/PLM-Features-Increasing-stockid-size
281	//   - TODO review by someone with more understanding of the code than the author
282	
283	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
284	ChangeColumnSize('itemcode', 'grns', 'VARCHAR(64)', ' NOT NULL ', '', '64');
285	// - no need, already changed in 4.3
286	//ChangeColumnSize('itemcode', 'purchorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
287	
288	
289	// 4.5 search for related columns with "id" in their name and change size
290	//   - https://github.com/timschofield/webERP/wiki/PLM-Features-Increasing-stockid-size
291	//   - TODO review by someone with more understanding of the code than the author
292	//   - note this column is the ONLY one with the size being changed that is _NOT_ the same
293	//     size as stockmaster.stockid (ediitemmapping is VARCHAR(50) not VARCHAR(20)). 
294	//     It will be assumed the size was a mistake and not investigated further.
295	
296	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
297	ChangeColumnSize('partnerstockid', 'ediitemmapping', 'VARCHAR(64)', ' NOT NULL ', '', '64');
298	
299	
300	// 5. INCREASE SIZE OF stockmaster.description FROM 50 CHAR TO 255 CHAR
301	//    - https://github.com/timschofield/webERP/discussions/812
302	//    - Parts&Vendors allows 255 char
303	//    - @pakricard OpenCart store allows 255 char 
304	
305	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
306	ChangeColumnSize('description', 'stockmaster', 'VARCHAR(255)', ' NOT NULL ', '', '255');
307	
308	
309	if ($_SESSION['Updates']['Errors'] == 0) {
310		UpdateDBNo(basename(__FILE__, '.php'), __('Increase stockmaster.stockid and description size'));
311	}
